import re
import json
import os
import asyncio
import base64
import threading
from http.server import BaseHTTPRequestHandler, HTTPServer
from telethon import TelegramClient, events
from telethon.errors import FloodWaitError
from telethon.tl.types import MessageService, MessageMediaWebPage

# ================= CONFIG =================

api_id = 21493021
api_hash = "724cd4ff94207025989137657bc78761"

source_channels = [
    -1001834311011,
    -1002626478225
]

destination_channel = -1002389291156
replace_username = "@apnahub69"

progress_file = "progress.json"
FIRST_RUN_LIMIT = 10
RECOVERY_LIMIT = 20
DELAY = 1

SESSION_B64 = """"""

# ===========================================

# ===== SESSION =====

if not os.path.exists("pro_session.session"):
    with open("pro_session.session", "wb") as f:
        f.write(base64.b64decode(SESSION_B64))

client = TelegramClient("pro_session", api_id, api_hash)

# ===== PROGRESS =====

def load_progress():
    if os.path.exists(progress_file):
        try:
            return json.load(open(progress_file))
        except:
            return {}
    return {}

def save_progress(data):
    json.dump(data, open(progress_file, "w"))

progress = load_progress()
seen_ids = set()

# ===== TEXT CLEAN =====

def clean_text(text):
    if not text:
        return ""

    text = re.sub(r'@\w+', replace_username, text)

    if replace_username not in text:
        text += f"\n\n{replace_username}"

    return text.strip()

# ===== ENTITY FIX =====

def fix_entities(text, entities):
    if not entities:
        return None
    return entities  # keep original (Telegram handles it)

# ===== PROCESS =====

async def process_message(message, source):

    if isinstance(message, MessageService):
        return

    if message.id in seen_ids:
        return

    seen_ids.add(message.id)

    raw_text = message.message or ""
    entities = fix_entities(raw_text, message.entities)
    text = clean_text(raw_text)

    try:
        await asyncio.sleep(DELAY)

        # MEDIA CASE
        if message.media and not isinstance(message.media, MessageMediaWebPage):

            await client.send_file(
                destination_channel,
                message.media,
                caption=text,
                formatting_entities=entities,
                buttons=message.buttons
            )
            print(f"[MEDIA] {source} | {message.id}")

        else:
            if text:
                await client.send_message(
                    destination_channel,
                    text,
                    formatting_entities=entities,
                    buttons=message.buttons,
                    link_preview=False
                )
                print(f"[TEXT] {source} | {message.id}")

    except FloodWaitError as e:
        print(f"⏳ FloodWait {e.seconds}s")
        await asyncio.sleep(e.seconds)
        await process_message(message, source)

    except Exception as e:
        print(f"[ERROR] {e}")
        with open("error.log", "a") as f:
            f.write(str(e) + "\n")

# ===== RECOVERY =====

async def recover():
    for source in source_channels:
        s = str(source)

        if s not in progress:
            async for msg in client.iter_messages(source, limit=FIRST_RUN_LIMIT, reverse=True):
                await process_message(msg, s)
                progress[s] = msg.id
                save_progress(progress)
            continue

        last = progress.get(s, 0)

        async for msg in client.iter_messages(source, min_id=last, reverse=True, limit=RECOVERY_LIMIT):
            await process_message(msg, s)
            progress[s] = msg.id
            save_progress(progress)

# ===== LIVE =====

@client.on(events.NewMessage(chats=source_channels))
async def handler(event):
    s = str(event.chat_id)
    msg = event.message

    if msg.id <= progress.get(s, 0):
        return

    await process_message(msg, s)
    progress[s] = msg.id
    save_progress(progress)

# ===== KEEP-ALIVE HTTP SERVER (Render health check) =====

class HealthHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        self.send_response(200)
        self.end_headers()
        self.wfile.write(b"ok")
    def log_message(self, format, *args):
        pass

def run_http_server():
    port = int(os.environ.get("PORT", 8000))
    server = HTTPServer(("0.0.0.0", port), HealthHandler)
    server.serve_forever()

threading.Thread(target=run_http_server, daemon=True).start()

# ===== MAIN =====

async def main():
    await client.start()
    await recover()
    print("🔥 ULTIMATE RUNNING...")
    await client.run_until_disconnected()

with client:
    client.loop.run_until_complete(main())